    #[test]
    fn test_copyto_basic() {
        let dst = vec![1, 2, 3, 4];
        let src = vec![10, 20, 30, 40];
        let mask = vec![false, true, false, true];
        let result = copyto(dst, src, mask);
        assert_eq!(result, vec![1, 20, 3, 40]);
    }

    #[test]
    fn test_copyto_all_true() {
        let dst = vec!['a', 'b', 'c'];
        let src = vec!['x', 'y', 'z'];
        let mask = vec![true, true, true];
        let result = copyto(dst, src, mask);
        assert_eq!(result, vec!['x', 'y', 'z']);
    }

    #[test]
